class BSTIterator:
    def __init__(self, root):
        self.st = []
        self._push(root)
    def _push(self, n):
        while n: self.st.append(n); n = n.left
    def next(self):
        n = self.st.pop()
        self._push(n.right)
        return n.val
    def hasNext(self):
        return bool(self.st)

class BSTIterator:
    def __init__(self, root):
        self.a = []; self.i = 0
        def dfs(n):
            if not n: return
            dfs(n.left); self.a.append(n.val); dfs(n.right)
        dfs(root)
    def next(self):
        v = self.a[self.i]; self.i += 1; return v
    def hasNext(self):
        return self.i < len(self.a)

def count_nodes(root):
    if not root: return 0
    def height(n):
        h = 0
        while n: h += 1; n = n.left
        return h
    hl = height(root.left); hr = height(root.right)
    if hl == hr:
        return (1 << hl) + count_nodes(root.right)
    else:
        return (1 << hr) + count_nodes(root.left)

def count_nodes(root):
