def lowest_common_ancestor(root, p, q):
    parent = {root: None}
    st = [root]
    while p not in parent or q not in parent:
        n = st.pop()
        if n.left: parent[n.left] = n; st.append(n.left)
        if n.right: parent[n.right] = n; st.append(n.right)
    seen = set()
    while p:
        seen.add(p); p = parent[p]
    while q not in seen:
        q = parent[q]
    return q

