def average_of_levels(root):
    if not root: return []
    res = []; q = deque([root])
    while q:
        s = 0; sz = len(q)
        for _ in range(sz):
            n = q.popleft(); s += n.val
            if n.left: q.append(n.left)
            if n.right: q.append(n.right)
        res.append(s / sz)
    return res

