def zigzag_level_order(root):
    if not root: return []
    res = []; q = deque([root]); rev = False
    while q:
        level = []; sz = len(q)
        for _ in range(sz):
            n = q.popleft(); level.append(n.val)
            if n.left: q.append(n.left)
            if n.right: q.append(n.right)
        res.append(level[::-1] if rev else level)
        rev = not rev
    return res
